script:
const AMB = "#d9822b", RED = "#c62828", MUT = "#5d7880", TEAL = "#2a9d8f";
let E = {};
function seg(api, t, a, b) { return api.seg(t, a, b, "ease_in_out"); }
function moveArt(api, id, parent) { const a = api.$(id); parent.appendChild(a); return a; }
function tag(api, g, txt, x, y, color) { return R.text(api, g, txt, x, y, {anchor: "middle", size: 16, weight: 800, color, halo: false}); }
function tile(api, g) {
  api.el("rect", {x: 46, y: 182, width: 164, height: 200, rx: 20, fill: "#fff6ea", stroke: AMB, "stroke-width": 3, "stroke-dasharray": "9 7"}, g);
}

function setup(api) {
  const A = api.$("#art"), L = api.el("g", {id: "lab2"}, api.svg);
  A.appendChild(api.$("#organ"));
  tile(api, A);
  tag(api, A, "CARCINOGEN", 128, 168, AMB);
  E.q = R.text(api, A, "?", 128, 308, {anchor: "middle", size: 92, weight: 800, color: AMB, halo: false});
  E.flaskG = api.el("g", {opacity: 0}, A); E.flaskG.appendChild(api.$("#flask"));
  E.cigG = api.el("g", {opacity: 0}, A); E.cigG.appendChild(api.$("#cig"));
  E.fring = api.el("rect", {x: 54, y: 196, width: 76, height: 180, rx: 16, fill: "none", stroke: RED, "stroke-width": 4, opacity: 0}, A);
  const P1 = api.el("path", {d: "M 214 290 C 260 290 290 300 352 306", fill: "none", stroke: "none"}, L);
  const P2 = api.el("path", {d: "M 214 318 C 260 318 290 322 352 322", fill: "none", stroke: "none"}, L);
  E.f1 = R.flow(api, A, P1, {n: 6, r: 5, color: "#f08a2c", period: 1700});
  E.f2 = R.flow(api, A, P2, {n: 6, r: 6, color: "#aeb8c0", period: 1900});
  E.ar1 = R.arrowGrow(api, A, "M 216 304 C 250 304 290 308 336 308", AMB, 6);
  E.ar2 = R.arrowGrow(api, A, "M 216 304 C 250 304 290 308 336 308", RED, 6);
  E.tum = R.lump(api, A, 402, 330, "tumour");
  E.glow = R.glow(api, A, 402, 330, {r: 40, color: "#e53935"});
  E.cOrg = [R.chip(api, L, "Urinary bladder", 400, 166, MUT, {size: 18}), R.leader(api, L, 450, 180, 450, 226, MUT)];
  E.cInh = R.chip(api, L, "Smoking, chemicals", 46, 414, AMB, {size: 18});
  E.cAns = R.chip(api, L, "Aniline dyes", 46, 414, RED, {size: 20});
  E.cTum = [R.chip(api, L, "Cancer", 500, 446, RED, {size: 18}), R.leader(api, L, 506, 430, 424, 346, RED)];
}
function render(t, api) {
  api.set(E.q, {opacity: (1 - seg(api, t, 2300, 2800)).toFixed(3)});
  R.fade(api, E.cOrg, t, 300, 800);
  const a2 = seg(api, t, 2400, 3000);
  api.set(E.flaskG, {opacity: a2.toFixed(3)});
  api.set(E.cigG, {opacity: (a2 * (1 - 0.6 * seg(api, t, 4700, 5300))).toFixed(3)});
  R.fade(api, E.cInh, t, 2700, 3200, 4650, 4950);
  E.f1.update(t, seg(api, t, 2700, 3200));
  E.f2.update(t, seg(api, t, 2700, 3200) * (1 - 0.7 * seg(api, t, 4700, 5300)));
  E.ar1.update(t, api.seg(t, 2500, 3500, "ease_in_out"));
  E.tum.update(t, seg(api, t, 3300, 4600), 30, 24, 0.5 * seg(api, t, 4600, 5000));
  E.ar2.update(t, api.seg(t, 4700, 5400, "ease_in_out"));
  E.glow.update(t, 0.8 * seg(api, t, 4700, 5300));
  api.set(E.fring, {opacity: seg(api, t, 4800, 5300).toFixed(3)});
  R.fade(api, E.cAns, t, 4900, 5400);
  R.fade(api, E.cTum, t, 5200, 5700);
}
